import{_ as e,c as n,o as a,ae as i}from"./chunks/framework.Bi6zybwU.js";const c=JSON.parse('{"title":"Frontend Editing","description":"Frontend Editing","frontmatter":{"title":"Frontend Editing","description":"Frontend Editing"},"headers":[],"relativePath":"guide/advanced-features/frontend-editing.md","filePath":"guide/advanced-features/frontend-editing.md"}'),o={name:"guide/advanced-features/frontend-editing.md"};function s(l,t,d,r,h,g){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="frontend-editing" tabindex="-1">Frontend Editing <a class="header-anchor" href="#frontend-editing" aria-label="Permalink to &quot;Frontend Editing&quot;">​</a></h1><p>Ninja Tables always offers fantastic features for its users, and one of them is the** Frontend Editing** feature. This functionality allows you to retrieve user data and edit the table data from the frontend. It also enables you to allow the user by role. This means that, in addition to some more possibilities, you can allow any specific user role to update or add data to your table. Let&#39;s dive into this guide which will demonstrate how to apply Frontend Editing on your Ninja Tables.</p><ul><li>With this feature, the user of this table will get some options, such as adding / editing or changing their own frontend data.</li><li>It is quite simple to implement this feature. Two options need to be configured in the Frontend Editing.</li><li>The first one is to set the <strong>user role</strong>, who can add/edit/delete data. And then set up the <strong>editable columns</strong>.</li></ul><h2 id="enabling-frontend-editing" tabindex="-1"><strong>Enabling Frontend Editing</strong> <a class="header-anchor" href="#enabling-frontend-editing" aria-label="Permalink to &quot;**Enabling Frontend Editing**&quot;">​</a></h2><ul><li>First, go to the Ninja Tables <strong>dashboard</strong> and click on the <strong>Frontend</strong> <strong>Editing</strong> tab. Look at the example below - <img src="https://ninjatables.com/wp-content/uploads/2022/09/Enable-Frontend-Editing-1-scaled.webp" alt="Enable Frontend Editing"></li><li>After enabling the frontend editing, a bunch of options will appear on this page. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Enable-Frontend-Editing-2-scaled.webp" alt="Frontend Settings"></li></ul><h3 id="user-role-permissions" tabindex="-1"><strong>User Role Permission</strong>s <a class="header-anchor" href="#user-role-permissions" aria-label="Permalink to &quot;**User Role Permission**s&quot;">​</a></h3><ul><li>Data editing permission is the first option in the settings. Here you will find some user roles to edit/add on the left side.</li><li>In the example given below, by checking both the left &amp; right checkboxes, only the Author is allowed to edit and delete the table data. Multiple users can be allowed permission if you want. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Enable-Frontend-Editing-3-scaled.webp" alt="Data Editing Permission"></li></ul><h3 id="own-data-only" tabindex="-1"><strong>Own Data Only</strong> <a class="header-anchor" href="#own-data-only" aria-label="Permalink to &quot;**Own Data Only**&quot;">​</a></h3><ul><li>If this feature is selected, then users cannot edit/delete <strong>other users’</strong> data. Only their own data can be edited.</li><li>You&#39;ll get a new **shortcode **for this table when you **allow **this &#39;Users can see and edit/delete only their own data&#39; permission. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Own-Data-Only--scaled.webp" alt="Own Data Only"></li></ul><p>Instead of using the standard table shortcode, use the <strong>following shortcode</strong> to display all the data without displaying <strong>Editing tools</strong> to all users.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_tables disable_edit=&quot;yes&quot; id=&quot;264&quot;]</span></span></code></pre></div><h3 id="editing-column-options" tabindex="-1"><strong>Editing Column Options</strong> <a class="header-anchor" href="#editing-column-options" aria-label="Permalink to &quot;**Editing Column Options**&quot;">​</a></h3><p>The user roles have already been set up. Then the column that can be editable needs to be set.</p><ul><li>We can select which column data to edit from the editing column options. And select the required along with the default value too. All the settings are completed; now you just need to update the settings. <img src="https://ninjatables.com/wp-content/uploads/2022/09/EDitable-Column-scaled.webp" alt="Editing Column Options"></li><li>So, now the table’s frontend is editable for the authors. In this case, just the authors can edit the table info from the frontend. But the other users cannot view the editable options.</li></ul><h2 id="few-optional-settings-of-the-frontend-editing-table" tabindex="-1"><strong>Few optional settings of the Frontend Editing table</strong> <a class="header-anchor" href="#few-optional-settings-of-the-frontend-editing-table" aria-label="Permalink to &quot;**Few optional settings of the Frontend Editing table**&quot;">​</a></h2><p>From the **Appearance Settings, **we can add some styling to our table.</p><h4 id="always-show-edit-icons" tabindex="-1"><strong>Always show edit icons</strong> <a class="header-anchor" href="#always-show-edit-icons" aria-label="Permalink to &quot;**Always show edit icons**&quot;">​</a></h4><ul><li>Enabling this option, lets you display the edit button beside the row on the frontend all the time. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Appearance-Settings--scaled.webp" alt="Appearance Settings"></li></ul><h2 id="frontend-editing-example" tabindex="-1">Frontend Editing Example <a class="header-anchor" href="#frontend-editing-example" aria-label="Permalink to &quot;Frontend Editing Example&quot;">​</a></h2><p><img src="https://ninjatables.com/wp-content/uploads/2022/11/frontend-edit-1-1024x477.png" alt="frontend editing in wordpress tables"> Note that, Only the Default table (manually created tables or constructed tables by importing CSV file) can be editable. All the other tables where table data are coming from other sources are restricted for front-end editing.</p>',20)])])}const p=e(o,[["render",s]]);export{c as __pageData,p as default};
